{
  "qa": [
    {
      "question": "借条与欠条在法律上存在哪些关键区别？",
      "answer": "借条对应借贷关系，欠条则可能涉及货款、分红、投资款等多种债务关系，两者在法律性质上完全不同。"
    },
    {
      "question": "借条的诉讼时效如何规定？",
      "answer": "借条的诉讼时效为三年，自还款之日起超过三年未向法院起诉的，法院将不再保护该债权。"
    },
    {
      "question": "民间借贷金额低于立案标准时，能否通过诉讼追偿？",
      "answer": "民间借贷金额低于立案标准（如两万元以下）时，虽可向法院提起诉讼，但若对方不承认债务，可能因诉讼成本过高导致实际追偿困难。"
    }
  ]
}
